import argparse,json,pathlib,subprocess,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);a=p.parse_args();out=a.directory.resolve();out.mkdir(parents=True,exist_ok=True);r=subprocess.run([str(a.executable),str(out)],capture_output=True,timeout=15);(out/'stdout.bin').write_bytes(r.stdout);(out/'stderr.bin').write_bytes(r.stderr);assert r.returncode==0 and not r.stderr,(r.returncode,r.stdout,r.stderr);v=json.loads((out/'attachment.json').read_text());assert v['summary']['expected']==1 and len(v['attachments'])==1;row=v['attachments'][0];assert row['name']=='meta\ud800\0<&' and row['contentType']=='application/octet-stream' and pathlib.Path(row['path']).read_bytes()==bytes([0,1,128,255]);assert row['writerExitConfirmed'] and row['writerExitCode']==0;x=ET.parse(out/'attachment.xml');props={p.attrib['name']:p.attrib['value'] for p in x.findall('.//property')};assert props['native.attachment1.nameXmlSanitizedUnits']=='2' and props['native.attachment1.path']==row['path'];html=(out/'attachment.html').read_text();assert 'original-json' in html and 'data-attachment-id="1"' in html;(out/'report.json').write_text(json.dumps({'passed':20,'scope':'Controlled report DTO validation20 plus independent real artifact bytes/JSON/XML/HTML; not an actual generic runner attempt'},indent=2)+'\n');print('PASS20 controlled attachment report validation and independent actual file decoding')
